package cn.zhuatech.cdp.controller; import cn.zhuatech.cdp.common.ApiResponse; import cn.zhuatech.cdp.dto.CdpDto.*; import cn.zhuatech.cdp.service.CdpService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('CDP_MANAGER','QUALITY','ADMIN')") public class CustomerDataAdminController {private final CdpService service;public CustomerDataAdminController(CdpService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<AudienceTaskView>> orders(){return ApiResponse.ok(service.audienceTasks());}}
